<template>
  <section class="project-space-panel">
    <header class="space-panel-header"><div><h2>{{ mode === 'meetings' ? '会议记录' : '项目概览' }}</h2><p>{{ mode === 'meetings' ? '已保存的客户沟通、访谈与会议纪要' : (meta?.name || '当前项目') }}</p></div><button type="button" :disabled="loading" @click="refresh"><i class="fa-solid fa-arrows-rotate"></i>{{ loading ? '读取中…' : '刷新' }}</button></header>
    <div v-if="error" class="space-panel-error" role="alert">{{ error }}<button type="button" @click="refresh">重试</button></div>
    <div v-if="loading" class="space-panel-empty">正在读取项目内容…</div>
    <template v-else-if="mode === 'meetings'">
      <div class="space-panel-tools"><input v-model="search" type="search" aria-label="搜索会议记录" placeholder="搜索记录名称…"><button type="button" @click="$emit('materials')">管理项目资料</button></div>
      <div v-if="filteredMeetings.length" class="space-meetings"><button v-for="file in filteredMeetings" :key="file.path" type="button" @click="$emit('open-source', file.path)"><i class="fa-regular fa-file-lines"></i><span><strong>{{ file.name }}</strong><small>{{ file.category }}<template v-if="file.updatedAt"> · {{ formatDate(file.updatedAt) }}</template></small></span><i class="fa-solid fa-chevron-right"></i></button></div>
      <div v-else class="space-panel-empty"><i class="fa-regular fa-clipboard"></i><h3>{{ search ? '没有匹配的记录' : '还没有已保存的会议记录' }}</h3><p>在项目资料中录入客户沟通，或导入会议纪要后会显示在这里。</p><button type="button" @click="$emit('materials')">前往项目资料</button></div>
    </template>
    <template v-else>
      <div class="space-overview-stats"><div><small>当前进度</small><strong>{{ stages.find(stage => stage.id === progressStage)?.label || `阶段 ${progressStage}` }}</strong></div><div><small>本地交付物</small><strong>{{ readyDocuments.length }} <em>份已生成</em></strong></div><div><small>项目资料</small><strong>{{ files.length }} <em>份原始资料</em></strong></div></div>
      <div class="space-overview-actions"><button type="button" class="primary" @click="$emit('resume')">继续当前任务 <i class="fa-solid fa-arrow-right"></i></button><button type="button" @click="$emit('materials')">查看项目资料</button></div>
      <h3 class="space-section-title">阶段与交付物</h3>
      <div class="space-stage-list"><section v-for="stage in stages" :key="stage.id"><header><span>{{ stage.id }}</span><h4>{{ stage.label }}</h4><small>{{ stageStatus[stage.id] === 'done' ? '已完成' : stage.id === progressStage ? '进行中' : stage.id < progressStage ? '可回看' : '未开始' }}</small></header><div v-if="documents.filter(doc => doc.stage === stage.id).length" class="space-stage-docs"><button v-for="doc in documents.filter(doc => doc.stage === stage.id)" :key="doc.file" type="button" :disabled="stage.id > progressStage" @click="$emit('open-document', {stage: stage.id, key: doc.key})"><span>{{ doc.name }}</span><small :class="doc.ready ? 'ready' : ''">{{ doc.ready ? '已生成' : '未生成' }}</small><i class="fa-solid fa-chevron-right"></i></button></div><p v-else class="space-stage-hint">{{ stage.id === 1 ? '资料准备与调研提纲在当前任务中查看' : '阶段内容在当前任务中查看' }}</p></section></div>
    </template>
  </section>
</template>
<script setup>
import { ref, computed, watch, onMounted } from 'vue';
const props = defineProps({slug:String, mode:{type:String,default:'overview'},meta:Object,progressStage:Number,stageStatus:{type:Object,default:()=>({})},stages:{type:Array,default:()=>[]}});
defineEmits(['materials','resume','open-source','open-document']);
const loading=ref(false),error=ref(''),files=ref([]),documents=ref([]),search=ref('');
const readyDocuments=computed(()=>documents.value.filter(doc=>doc.ready));
const meetings=computed(()=>files.value.filter(file=>/会议|纪要|沟通|访谈|客户对接|meeting|minutes|interview/i.test(`${file.category} ${file.name} ${file.path}`)).sort((a,b)=>(Number(b.updatedAt)||Date.parse(b.updatedAt)||0)-(Number(a.updatedAt)||Date.parse(a.updatedAt)||0)));
const filteredMeetings=computed(()=>meetings.value.filter(file=>`${file.name} ${file.category}`.toLowerCase().includes(search.value.trim().toLowerCase())));
function formatDate(value){const date=new Date(value);return Number.isNaN(date.getTime())?'':date.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}
let sequence=0;
async function refresh(){const seq=++sequence;loading.value=true;error.value='';try{const groups=await Promise.all(['knowledge','uploads'].map(async dir=>{const result=await window.api.hermes.listFiles(props.slug,dir,true);if(!result?.success)throw Error(result?.error||'项目资料读取失败');return(result.files||[]).filter(file=>!file.isDirectory).map(file=>({name:file.name.replace(/^\d{4}-\d{2}-\d{2}-(.+)-\d{13}\.md$/,'$1'),path:`${dir}/${file.relPath||file.name}`,category:dir==='uploads'?'对话附件':(file.relPath||'').includes('/')?file.relPath.split('/')[0]:'参考资料',updatedAt:file.mtimeMs||file.modifiedAt||0}));}));if(window.api.library?.linked){const linked=await window.api.library.linked(props.slug);if(!linked?.success)throw Error(linked?.error||'关联资料读取失败');groups.push((linked.entries||[]).filter(entry=>!entry.deletedAt).map(entry=>({name:entry.title,path:`library/${entry.id}`,category:'关联资料库',updatedAt:entry.updatedAt||entry.createdAt})));}const all=props.stages.flatMap(stage=>(stage.documents||[]).map(doc=>({...doc,stage:stage.id})));const checked=await Promise.all(all.map(async doc=>{const outputs=await Promise.all((doc.files||[doc.file]).map(file=>window.api.hermes.readFile(props.slug,file)));return{...doc,ready:outputs.every(result=>!!(result?.success&&String(result.content||'').trim()))};}));if(seq!==sequence)return;files.value=[...new Map(groups.flat().map(file=>[file.path,file])).values()];documents.value=checked;}catch(e){if(seq===sequence){files.value=[];documents.value=[];error.value=e.message||'项目内容读取失败';}}finally{if(seq===sequence)loading.value=false;}}
onMounted(refresh);watch(()=>props.slug,refresh);
</script>
<style>
.project-space-panel{flex:1;min-width:0;min-height:0;overflow:auto;padding:24px 28px;color:#334155;background:#fff;font-size:13px;line-height:1.6}.space-panel-header{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:22px}.space-panel-header h2{font-size:20px;font-weight:600;color:#172036}.space-panel-header p{font-size:13px;color:#64748b;margin-top:4px}.project-space-panel button{font-size:12px;line-height:1.5;border:1px solid #dbe4f0;border-radius:8px;background:#fff;padding:8px 12px;color:#475569;cursor:pointer}.project-space-panel button:hover:not(:disabled){border-color:#93b4fb;background:#f5f8ff;color:#2563eb}.project-space-panel button:disabled{opacity:.55;cursor:not-allowed}.project-space-panel button i{margin-right:6px}.project-space-panel button.primary{background:#2563eb;border-color:#2563eb;color:#fff}.space-panel-error{padding:12px 14px;margin-bottom:16px;border-radius:8px;background:#fff1f2;color:#b91c1c}.space-panel-error button{margin-left:12px}.space-panel-tools{display:flex;gap:12px;margin-bottom:16px}.space-panel-tools input{flex:1;min-width:0;border:1px solid #dbe4f0;border-radius:8px;padding:8px 12px;font-size:13px}.space-panel-empty{padding:48px 20px;text-align:center;color:#64748b}.space-panel-empty>i{display:block;font-size:30px;margin-bottom:14px;color:#a9bad3}.space-panel-empty h3{font-size:15px;font-weight:500;color:#475569}.space-panel-empty p{margin:8px 0 16px}.space-meetings{display:grid;gap:8px}.space-meetings button{display:flex;align-items:center;gap:12px;padding:14px;text-align:left}.space-meetings button>i:first-child{font-size:18px;color:#2563eb}.space-meetings button>span{flex:1;min-width:0}.space-meetings strong{display:block;font-size:13px;font-weight:500;overflow-wrap:anywhere}.space-meetings small{display:block;margin-top:3px;font-size:11px;color:#94a3b8}.space-meetings button>i:last-child{font-size:10px;color:#94a3b8}.space-overview-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:20px}.space-overview-stats>div{padding:16px;background:#f6f9ff;border:1px solid #e8eef8;border-radius:10px}.space-overview-stats small{display:block;font-size:12px;color:#64748b;margin-bottom:6px}.space-overview-stats strong{font-size:20px;font-weight:600;color:#1d4ed8}.space-overview-stats em{font-size:12px;font-style:normal;font-weight:400;color:#64748b}.space-overview-actions{display:flex;gap:10px;margin-bottom:26px}.space-section-title{font-size:14px;font-weight:600;margin-bottom:12px;color:#172036}.space-stage-list{display:grid;gap:12px}.space-stage-list>section{border:1px solid #e2e8f0;border-radius:10px;overflow:hidden}.space-stage-list header{display:flex;align-items:center;gap:10px;padding:12px 14px;background:#fafcff}.space-stage-list header>span{width:24px;height:24px;display:grid;place-items:center;border-radius:7px;background:#edf3ff;color:#2563eb;font-size:12px}.space-stage-list h4{font-size:13px;font-weight:600;flex:1}.space-stage-list header>small{font-size:11px;color:#64748b}.space-stage-docs{padding:4px 14px}.space-stage-docs button{display:flex;align-items:center;gap:12px;width:100%;padding:10px 0;border:0;border-radius:0;text-align:left;border-bottom:1px solid #f1f5f9}.space-stage-docs button:last-child{border-bottom:0}.space-stage-docs span{flex:1;min-width:0;overflow-wrap:anywhere}.space-stage-docs small{font-size:11px;color:#94a3b8}.space-stage-docs small.ready{color:#059669}.space-stage-docs i{font-size:9px;color:#94a3b8}.space-stage-hint{font-size:12px;color:#64748b;padding:12px 14px}@media(max-width:900px){.project-space-panel{padding:20px}.space-overview-stats strong{font-size:16px}}
</style>
